extern "C" float fmodf(float, float);
extern bool blocked_by_wave();

struct board_controller
{
  char pad[3552];
  int region;
  int GetRegion() const { return region; }
};

struct kellyslater_controller
{
  board_controller board;
  board_controller& get_board_controller() { return board; }
};

struct game
{
  char pad[188];
  int active_player;
  int get_active_player() const { return active_player; }
};

struct world_dynamics_system
{
  char pad[248];
  kellyslater_controller* controllers[2];
  kellyslater_controller* get_ks_controller(int n) { return controllers[n]; }
};

extern game* g_game_ptr;
extern world_dynamics_system* g_world_ptr;
__asm__(".equ g_game_ptr,0x0045AC64");
__asm__(".equ g_world_ptr,0x00431A8C");

template<class T> T range(T v, T lo, T hi)
{
  return v < lo ? lo : (v > hi ? hi : v);
}

struct lensflare
{
  char pad0[8];
  struct vtable_t
  {
    char pad[248];
    short delta;
    short unused;
    void (*set_active)(void*, bool);
  }* vtable;
  char pad1[504];
  float speed;
  char pad2[4];
  float amount;
  float target;
  char pad3[228];
  float los_time;
  float los_freq;

  void set_active(bool active)
  {
    vtable->set_active((char*)this + vtable->delta, active);
  }

  void frame_advance(float t);
};

void lensflare::frame_advance(float t)
{
  float d = fmodf(t, los_freq);
  los_time += d;
  if (los_time >= los_freq)
  {
    bool v = false;

    if (blocked_by_wave() || g_world_ptr->get_ks_controller(g_game_ptr->get_active_player())->get_board_controller().GetRegion() == 9)
      v = true;
    target = v ? 0.0f : 1.0f;
    los_time -= los_freq;
  }

  float diff = target - amount;
  float dmax = t * speed;
  diff = range(diff, -dmax, dmax);
  amount += diff;

  set_active(true);
}
